                    createdKey = parsed && (parsed.key || parsed.id) ? (parsed.key || parsed.id) : null;
                } catch (e) { /* key extraction failed — non-critical */ }

                console.log('Created Sub-task ' + (createdKey || '(key unavailable)') + ': ' + summary);
