            {
                name: 'backend-service',
                tasks: [
                    { id: 'schema', title: 'Schema' },
                    { id: 'processor', title: 'Processor' }
                ]
            },
            {
                name: 'frontend-app',
                tasks: [
                    { id: 'view', title: 'View', depends_on: ['backend-service:processor'] }
                ]
            }
